package dev.freelocs.aetherion.gui.engine

import dev.freelocs.aetherion.gui.theme.Colors
import net.minecraft.client.gui.Font
import net.minecraft.client.gui.GuiGraphicsExtractor
import net.minecraft.client.renderer.RenderPipelines
import net.minecraft.resources.Identifier

/**
 * Rendering primitives on top of Minecraft's GUI render-state API ([GuiGraphicsExtractor]).
 *
 * - Rounded fills/rings/glows are nine-slice GUI sprites (generated by `tools/gen_sprites.py`) tinted at
 *   draw time, so a rounded rect is a single textured quad batch instead of dozens of scanline fills.
 *   Sprites are supersampled, which keeps corners smooth at any GUI scale.
 * - Every color passes through [alpha], so a whole subtree can fade (page transitions, GUI fade-in).
 * - Nothing here allocates per call except [fit] on cache misses.
 */
object Draw {
    private const val NS = "aetherion"
    private val RADII = intArrayOf(2, 3, 4, 5, 6, 8, 10, 12, 14, 16, 20)
    private val fills = Array(RADII.size) { Identifier.fromNamespaceAndPath(NS, "ui/r${RADII[it]}") }
    private val rings = Array(RADII.size) { Identifier.fromNamespaceAndPath(NS, "ui/b${RADII[it]}") }
    private val glowBig = Identifier.fromNamespaceAndPath(NS, "ui/glow")
    private val glowSmall = Identifier.fromNamespaceAndPath(NS, "ui/glow_s")
    private val logo = Identifier.fromNamespaceAndPath(NS, "icon.png")

    private const val GLOW_BIG_EXTENT = 14
    private const val GLOW_SMALL_EXTENT = 8

    lateinit var g: GuiGraphicsExtractor
        private set
    lateinit var font: Font
        private set

    /** Global opacity multiplier applied to every color. */
    var alpha = 1f

    /** Draw calls issued since [begin]; read by the performance page. */
    var calls = 0
        private set

    private var scissorDepth = 0

    fun begin(graphics: GuiGraphicsExtractor, f: Font) {
        g = graphics; font = f; alpha = 1f; calls = 0; scissorDepth = 0
    }

    private fun col(c: Int): Int {
        if (alpha >= 1f) return c
        val a = (((c ushr 24) and 0xFF) * alpha + 0.5f).toInt()
        return (a shl 24) or (c and 0xFFFFFF)
    }

    private fun visible(c: Int) = ((c ushr 24) and 0xFF) != 0 && alpha > 0.004f

    private fun pick(r: Int, w: Int, h: Int): Int {
        val m = minOf(r, w / 2, h / 2)
        var best = -1
        for (i in RADII.indices) if (RADII[i] <= m) best = i else break
        return best
    }

    fun rect(x: Int, y: Int, w: Int, h: Int, color: Int) {
        if (w <= 0 || h <= 0 || !visible(color)) return
        calls++
        g.fill(x, y, x + w, y + h, col(color))
    }

    fun round(x: Int, y: Int, w: Int, h: Int, radius: Int, color: Int) {
        if (w <= 0 || h <= 0 || !visible(color)) return
        val i = pick(radius, w, h)
        calls++
        if (i < 0) g.fill(x, y, x + w, y + h, col(color))
        else g.blitSprite(RenderPipelines.GUI_TEXTURED, fills[i], x, y, w, h, col(color))
    }

    /** Hairline rounded border (about half a GUI unit thick). */
    fun ring(x: Int, y: Int, w: Int, h: Int, radius: Int, color: Int) {
        if (w <= 0 || h <= 0 || !visible(color)) return
        val i = pick(radius, w, h)
        calls++
        if (i < 0) {
            val c = col(color); g.outline(x, y, w, h, c)
        } else g.blitSprite(RenderPipelines.GUI_TEXTURED, rings[i], x, y, w, h, col(color))
    }

    /** Soft shadow/glow hugging the rect; [big] selects the wide (14 unit) or tight (8 unit) falloff. */
    fun glow(x: Int, y: Int, w: Int, h: Int, color: Int, big: Boolean = true) {
        if (!visible(color)) return
        val useBig = big && w >= 20 && h >= 20
        if (!useBig && (w < 12 || h < 12)) return
        val e = if (useBig) GLOW_BIG_EXTENT else GLOW_SMALL_EXTENT
        calls++
        g.blitSprite(RenderPipelines.GUI_TEXTURED, if (useBig) glowBig else glowSmall, x - e, y - e, w + 2 * e, h + 2 * e, col(color))
    }

    fun vGradient(x: Int, y: Int, w: Int, h: Int, top: Int, bottom: Int) {
        if (w <= 0 || h <= 0) return
        calls++
        g.fillGradient(x, y, x + w, y + h, col(top), col(bottom))
    }

    /** Horizontal gradient drawn as a bounded number of vertical strips. */
    fun hGradient(x: Int, y: Int, w: Int, h: Int, left: Int, right: Int) {
        if (w <= 0 || h <= 0) return
        val strips = minOf(w, 32)
        for (i in 0 until strips) {
            val x0 = x + w * i / strips
            val x1 = x + w * (i + 1) / strips
            if (x1 > x0) rect(x0, y, x1 - x0, h, Colors.lerp(left, right, (i + 0.5f) / strips))
        }
    }

    // ── text ────────────────────────────────────────────────────────────────

    val lineHeight get() = font.lineHeight

    fun textWidth(s: String) = font.width(s)

    fun text(s: String, x: Int, y: Int, color: Int, shadow: Boolean = false) {
        if (s.isEmpty() || !visible(color)) return
        calls++
        g.text(font, s, x, y, col(color), shadow)
    }

    fun textCentered(s: String, cx: Int, y: Int, color: Int, shadow: Boolean = false) = text(s, cx - font.width(s) / 2, y, color, shadow)

    fun textRight(s: String, right: Int, y: Int, color: Int) = text(s, right - font.width(s), y, color)

    /** Vertically centres a single line inside [h]. */
    fun textMiddle(s: String, x: Int, y: Int, h: Int, color: Int) = text(s, x, y + (h - 8) / 2, color)

    private class FitEntry { var width = -1; var result = "" }

    private val fitCache = HashMap<String, FitEntry>()

    /**
     * Returns [s] shortened with an ellipsis to fit [maxW]. Each string remembers its last result, so a
     * label rendered every frame at a stable width costs one hash lookup and no allocation.
     */
    fun fit(s: String, maxW: Int): String {
        if (maxW <= 0) return ""
        if (font.width(s) <= maxW) return s
        if (fitCache.size > 1024) fitCache.clear()
        val e = fitCache.getOrPut(s) { FitEntry() }
        if (e.width != maxW) {
            e.width = maxW
            e.result = font.plainSubstrByWidth(s, (maxW - font.width("…")).coerceAtLeast(0)) + "…"
        }
        return e.result
    }

    // ── icons & images ──────────────────────────────────────────────────────

    /** Draws an 8x8 [icon] at integer [scale] (so 8*scale GUI units wide). */
    fun icon(icon: Icon, x: Int, y: Int, scale: Int, color: Int) {
        if (!visible(color)) return
        val c = col(color)
        val r = icon.rects
        var i = 0
        while (i < r.size) {
            g.fill(x + r[i] * scale, y + r[i + 1] * scale, x + (r[i] + r[i + 2]) * scale, y + (r[i + 1] + r[i + 3]) * scale, c)
            calls++
            i += 4
        }
    }

    fun logo(x: Int, y: Int, size: Int) {
        if (alpha <= 0.004f) return
        calls++
        g.blit(RenderPipelines.GUI_TEXTURED, logo, x, y, 0f, 0f, size, size, size, size, col(-1))
    }

    // ── clipping & transforms ───────────────────────────────────────────────

    fun pushClip(x: Int, y: Int, w: Int, h: Int) {
        g.enableScissor(x, y, x + maxOf(w, 0), y + maxOf(h, 0))
        scissorDepth++
    }

    fun popClip() {
        if (scissorDepth > 0) { g.disableScissor(); scissorDepth-- }
    }

    /** Scales around ([cx],[cy]); pair with [popTransform]. */
    fun pushScale(cx: Float, cy: Float, scale: Float) {
        val p = g.pose()
        p.pushMatrix()
        p.translate(cx, cy)
        p.scale(scale, scale)
        p.translate(-cx, -cy)
    }

    fun popTransform() { g.pose().popMatrix() }

    /** Starts a new draw layer so subsequent elements always render above everything drawn so far. */
    fun nextLayer() = g.nextStratum()

    fun blurBehind() = g.blurBeforeThisStratum()
}
